package com.donotmiss.backend.aiapplication.career.gap;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="gap_analysis_items") public class GapAnalysisItemEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="gap_analysis_id",nullable=false,updatable=false) private Long gapAnalysisId; @Column(name="requirement_id",nullable=false,updatable=false) private Long requirementId; @Column(name="skill_code",nullable=false,length=100,updatable=false) private String skillCode; @Column(name="requirement_text",nullable=false,columnDefinition="text",updatable=false) private String requirementText; @Column(nullable=false,updatable=false) private int importance; @Column(name="required_level",nullable=false,length=80,updatable=false) private String requiredLevel; @Enumerated(EnumType.STRING) @Column(nullable=false,length=16,updatable=false) private GapStatus status; @Column(name="candidate_evidence_ids_json",nullable=false,columnDefinition="json",updatable=false) private String candidateEvidenceIdsJson; @Enumerated(EnumType.STRING) @Column(name="evidence_strength",nullable=false,length=16,updatable=false) private EvidenceStrength evidenceStrength; @Column(nullable=false,precision=5,scale=4,updatable=false) private BigDecimal confidence; @Column(nullable=false,length=1200,updatable=false) private String reason; @Column(name="source_chunk_id",nullable=false,updatable=false) private Long sourceChunkId; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;
 @PrePersist void create(){if(createdAt==null)createdAt=Instant.now();} public Long getId(){return id;} public Long getGapAnalysisId(){return gapAnalysisId;} public void setGapAnalysisId(Long v){gapAnalysisId=v;} public Long getRequirementId(){return requirementId;} public void setRequirementId(Long v){requirementId=v;} public String getSkillCode(){return skillCode;} public void setSkillCode(String v){skillCode=v;} public String getRequirementText(){return requirementText;} public void setRequirementText(String v){requirementText=v;} public int getImportance(){return importance;} public void setImportance(int v){importance=v;} public String getRequiredLevel(){return requiredLevel;} public void setRequiredLevel(String v){requiredLevel=v;} public GapStatus getStatus(){return status;} public void setStatus(GapStatus v){status=v;} public String getCandidateEvidenceIdsJson(){return candidateEvidenceIdsJson;} public void setCandidateEvidenceIdsJson(String v){candidateEvidenceIdsJson=v;} public EvidenceStrength getEvidenceStrength(){return evidenceStrength;} public void setEvidenceStrength(EvidenceStrength v){evidenceStrength=v;} public java.math.BigDecimal getConfidence(){return confidence;} public void setConfidence(java.math.BigDecimal v){confidence=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public Long getSourceChunkId(){return sourceChunkId;} public void setSourceChunkId(Long v){sourceChunkId=v;} public Instant getCreatedAt(){return createdAt;}
}
